"use strict";
const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const form=document.querySelector('#recovery-form'),status=document.querySelector('#recovery-status');
if(token){document.querySelector('#email-label').hidden=true;form.elements.email.disabled=true;document.querySelector('#password-label').hidden=false;form.elements.password.disabled=false;form.elements.password.required=true;form.querySelector('button').textContent='Salva nuova password';document.querySelector('#recovery-info').textContent='Scegli almeno 12 caratteri. Le sessioni precedenti verranno chiuse.'}
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const r=await fetch('/api/'+(token?'password-reset':'password-request'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(token?{token,password:form.elements.password.value}:{email:form.elements.email.value})});const d=await r.json();if(!r.ok)throw Error(d.error);status.textContent=d.message; if(token){form.elements.password.value='';form.elements.password.disabled=true;}else button.disabled=false;}catch(e){status.textContent=e.message;button.disabled=false;}});
